// ── ASSEMBLE ALL PROPERTIES ───────────────────────────────────────────────────
const properties = [
  ...mapProps(rawCABA, 'Buenos Aires Capital', 'Buenos Aires'),
  ...mapProps(rawGBANorte, 'GBA Norte', 'Buenos Aires'),
  ...mapProps(rawGBAOeste, 'GBA Oeste', 'Buenos Aires'),
  ...mapProps(rawGBASur, 'GBA Sur', 'Buenos Aires'),
  ...mapProps(rawRosario, 'Rosario', 'Santa Fe'),
  ...mapProps(rawMendoza, 'Mendoza', 'Mendoza'),
  ...mapProps(rawSalta, 'Salta', 'Salta'),
  ...mapProps(rawTucuman, 'San Miguel de Tucumán', 'Tucumán'),
  ...mapProps(rawNeuquen, 'Neuquén', 'Neuquén'),
  ...mapProps(rawBariloche, 'Bariloche', 'Río Negro'),
];

async function seed() {
  await mongoose.connect(MONGODB_URI);
  let inserted = 0, skipped = 0, errors = 0;
  const byCity: Record<string, number> = {};

  for (const p of properties) {
    try {
      await Property.findOneAndUpdate(
        { slug: p.slug },
        p,
        { upsert: true, new: true }
      );
      inserted++;
      byCity[p.ciudad!] = (byCity[p.ciudad!] || 0) + 1;
    } catch (e: any) {
      if (e.code === 11000) skipped++;
      else { console.error('Error:', e.message); errors++; }
    }
  }

  console.log(`\nSeed completado`);
  console.log(`   Insertadas/actualizadas: ${inserted}`);
  console.log(`   Duplicados ignorados: ${skipped}`);
  console.log(`   Errores: ${errors}`);
  console.log(`\nPor ciudad:`);
  for (const [city, count] of Object.entries(byCity)) {
    console.log(`   ${city}: ${count}`);
  }
  await mongoose.disconnect();
}

seed().catch(console.error);
